/* hello487: every SOL_IPV6 and SOL_IP option number 0..79 on a UDP socket answers like Linux. A: getsockopt on a fresh socket
 * (the returned length, or the errno). B: on a fresh socket per option, setsockopt of 1, 255, 256 and -1 in turn, each followed by
 * getsockopt (its value, -1000 when it fails): what is accepted, what is EINVAL, how the value reads back. Both tables were measured
 * on the host (gcc -DHOST: the same program, compared against itself). */
#ifdef HOST
#define _GNU_SOURCE
#include <errno.h>
#include <stdio.h>
#include <sys/socket.h>
#include <unistd.h>
static long sock(int f, int t, int p) { long r = socket(f, t, p); return r < 0 ? -errno : r; }
static long getopt_(long s, int lv, int o, void *v, unsigned *l) { long r = getsockopt((int)s, lv, o, v, (socklen_t *)l); return r < 0 ? -errno : r; }
static long setopt_(long s, int lv, int o, const void *v, unsigned l) { long r = setsockopt((int)s, lv, o, v, l); return r < 0 ? -errno : r; }
static void close_(long s) { close((int)s); }
static void print(const char *s) { fputs(s, stdout); fflush(stdout); }
#else
#include "../lib/moqi_libc/include/moqi_syscalls.h"
#include "../lib/moqi_libc/include/stdio.h"
static long sock(int f, int t, int p) { return syscall3(117, f, t, p); }
static long getopt_(long s, int lv, int o, void *v, unsigned *l) { return syscall5(133, s, lv, o, (long)v, (long)l); }
static long setopt_(long s, int lv, int o, const void *v, unsigned l) { return syscall5(132, s, lv, o, (long)v, l); }
static void close_(long s) { syscall1(11, s); }
#endif
static const int want[2][80] = {
    { -92, -107, 4, 4, 4, 4, -92, -92, 4, -92, -92, 4, -92, -92, -92, -92, 4, 4, 4, 4, -92, -92, 4, 4, -107, 4, 4, -92, -92, 4, 4, 4, -2, 4, -92, -92, -92, -92, -92, -92, -92, -92, -92, -92, -92, -92, -92, -92, -99, 4, -92, 4, -92, 4, 0, 0, 4, 0, 4, 0, 4, -107, 4, -92, -92, -92, 4, 4, -92, -92, 4, -92, 4, 4, 4, 4, 4, 4, 4, -92 },
    { -92, 4, 4, 4, 0, 4, 4, 4, 4, -92, 4, 4, 4, 4, -107, 4, -92, -92, 4, 4, 4, 4, 4, 4, 4, 4, 4, -92, -92, -92, -92, -92, 4, 4, 4, -92, -92, -92, -92, -92, -92, -22, -92, -92, -92, -92, -92, -92, -22, 4, 4, 4, 4, -92, -92, -92, -92, -92, -92, -92, -92, -92, -92, -92, -92, -92, -92, -92, -92, -92, -92, -92, -92, -92, -92, -92, -92, -92, -92, -92 },
};
